import struct, re, sys
def yaps(f):
    with open(f,'rb') as fh:
        hd0,n = struct.unpack('<II', fh.read(8))
        e = [fh.read(152) for _ in range(n)][-1]
        off = struct.unpack('<Q', e[8:16])[0]
        fh.seek(off); hl = struct.unpack('<I', fh.read(4))[0]; h = fh.read(hl)
    i = h.find(b'### ASCCONV BEGIN'); y = h[i:h.find(b'### ASCCONV END', i)].decode(errors='replace')
    d = {}
    for line in y.splitlines():
        m = re.match(r'^(\S+)\s*=\s*(.+)$', line)
        if m: d[m.group(1)] = m.group(2).strip()
    return d
a, b = yaps(sys.argv[1]), yaps(sys.argv[2])
for k in sorted(set(a)|set(b)):
